for (const id in CHUNKS) {
  const ch = CHUNKS[id];
  const w = Math.max(...ch.rows.map(r => r.length));
  const pad = Array.from({ length: 13 - ch.rows.length }, () => '.'.repeat(w));
  ch.rows = pad.concat(ch.rows).map(r => r.padEnd(w, '.'));
  ch.w = w; ch.id = id;
}

