  if (Math.abs(tx - pt.x) > 12) { pt.x = tx; pt.y = ty; }      // a respawn: catch up at once
  const spd = Math.hypot(tx - pt.x, ty - pt.y);
  pt.x += (tx - pt.x) * Math.min(1, dt * 4); pt.y += (ty - pt.y) * Math.min(1, dt * 6);
