    ctx.fillStyle = it.col ? `rgba(255,143,179,${0.16 + 0.16 * pu})` : `rgba(143,196,255,${0.16 + 0.16 * pu})`; ell(ctx, X, Y, TP * (0.62 + 0.08 * pu), TP * (0.62 + 0.08 * pu)); ctx.fill();
    drawKey(X, Y, TP * 0.95, it.col);
