    for (const px of [0.18, 0.82]) { const x = X + Wd * px - 5 * u; rrect(ctx, x, Y + Hd - 4 * u, 10 * u, sy(f.foot) - (Y + Hd) + 4 * u, 3 * u); ctx.fill(); ctx.stroke(); }
