  ctx.fillStyle = 'rgba(166,119,24,.9)'; ctx.font = `800 ${Math.round(TP * 0.32)}px ${FONT}`; ctx.textAlign = 'center'; ctx.fillText('放这里', sx(s.x), top + H * 0.62);
