    for (let k = 0; k < 4; k++) { ctx.fillStyle = k % 2 ? '#E9707F' : '#FFFFFF'; ctx.fillRect(X - (0.42 - k * 0.04) * TP, sea - (0.6 + k * 0.6) * TP, (0.84 - k * 0.08) * TP, 0.6 * TP); }
