  const col = pt.hue ? ['#C69CFF', '#8A5BD6'] : ['#8FC4FF', '#4C8FD6'];
  ctx.fillStyle = on ? col[0] : '#C9C4D6'; ctx.strokeStyle = on ? col[1] : '#9A94AA'; ctx.lineWidth = 6 * u;
  ell(ctx, X, Y - 85 * u, 46 * u, 80 * u); ctx.fill(); ctx.stroke();
  ctx.fillStyle = on ? 'rgba(255,255,255,.85)' : 'rgba(255,255,255,.35)'; ell(ctx, X, Y - 85 * u, 30 * u, 62 * u); ctx.fill();
  if (on && !REDUCE) { ctx.strokeStyle = col[0]; ctx.lineWidth = 4 * u; ctx.beginPath(); ctx.arc(X, Y - 85 * u, 20 * u, G.clock * 3, G.clock * 3 + 4.4); ctx.stroke(); }
