  ctx.fillStyle = 'rgba(40,20,30,.18)'; ell(ctx, X, Y - 2 * u, 22 * u, 5 * u); ctx.fill();
  if (l.lit) { ctx.fillStyle = 'rgba(255,217,130,.35)'; ell(ctx, X, Y - 168 * u, 46 * u, 46 * u); ctx.fill(); }
  ctx.fillStyle = l.lit ? '#FFD982' : '#9C8FB0'; ctx.strokeStyle = '#6B5A7E'; ctx.lineWidth = 4 * u;
