  ctx.fillStyle = '#D6A26A'; rrect(ctx, X + 8 * u, Y + 8 * u, s - 16 * u, s - 16 * u, 10 * u); ctx.fill();
  ctx.strokeStyle = '#9C6B3E'; ctx.lineWidth = 9 * u; ctx.beginPath(); ctx.moveTo(X + 14 * u, Y + 14 * u); ctx.lineTo(X + s - 14 * u, Y + s - 14 * u); ctx.stroke();
