  const X = sx(s.x0), Y = sy(s.y), w = (s.x1 - s.x0) * TP, u = TP / 100, sq = s.squash;
  ctx.strokeStyle = '#8D95AE'; ctx.lineWidth = 6 * u; ctx.beginPath();
  const bot = sy(s.y + 0.55), top = Y + sq * 0.22 * TP + 10 * u;
