    if (r === 5) { ctx.fillStyle = '#FFD75E'; rrect(ctx, X + 30 * u, Y + 30 * u, 40 * u, 34 * u, 6 * u); ctx.fill(); ctx.strokeStyle = '#FFD75E'; ctx.lineWidth = 7 * u; ctx.beginPath(); ctx.arc(X + 50 * u, Y + 30 * u, 13 * u, Math.PI, 0); ctx.stroke(); }
