    const up = (e) => { const s = ptrs.get(e.pointerId); if (!s) return; s.knob.remove(); ptrs.delete(e.pointerId); if (!ptrs.size) { const t = TOUCH.duo[z]; t.l = t.r = t.j = 0; } };
