  if (BT.mode === 'bot') { const bot = other(API.me); for (const b of R0.beats) if (b['bot_' + bot] != null && b[bot] == null && now >= b.t + b['bot_' + bot]) { b[bot] = b['bot_' + bot]; beatFlash(bot); } }
